import pandas as pd
import requests
from datetime import datetime, timezone

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

API_KEY = CREDENTIALS.get('FRED_API_KEY', '')
BASE = 'https://api.stlouisfed.org/fred/series/observations'

EXPECTED_COLUMNS = [
    'series_id', 'description', 'index_scope',
    'latest_value', 'latest_date',
    'value_30d_ago', 'value_90d_ago', 'value_1y_ago',
    'change_30d_pct', 'change_90d_pct', 'change_1y_pct',
    'percentile_1y', 'regime_flag',
    'investment_thesis', 'etf_long', 'etf_short', '_epoch',
]

SERIES = [
    {'id': 'DTWEXBGS', 'desc': 'Trade Weighted USD: Broad (all partners)', 'scope': 'broad', 'long': 'UUP', 'short': 'UDN'},
    {'id': 'DTWEXAFEGS', 'desc': 'Trade Weighted USD: Advanced Foreign Economies (DXY-like)', 'scope': 'advanced', 'long': 'UUP', 'short': 'UDN'},
    {'id': 'DTWEXEMEGS', 'desc': 'Trade Weighted USD: Emerging Market Economies', 'scope': 'em', 'long': 'UUP', 'short': 'EEM'},
]

def compute_change_pct(latest, prior):
    if latest is None or prior is None:
        return None
    if prior == 0:
        return None
    return round(((latest - prior) / prior) * 100.0, 2)

def compute_percentile(values, target):
    if not values:
        return None
    below = 0
    total = 0
    for vi in range(len(values)):
        v = values[vi]
        if v is None:
            continue
        total = total + 1
        if v <= target:
            below = below + 1
    if total == 0:
        return None
    return round(100.0 * below / total, 1)

def classify_regime(percentile, change_30d_pct):
    if percentile is None:
        return 'UNKNOWN'
    if percentile >= 90 and change_30d_pct is not None and change_30d_pct >= 1.0:
        return 'BREAKING_OUT'
    if percentile >= 70:
        return 'STRONG'
    if percentile <= 10 and change_30d_pct is not None and change_30d_pct <= -1.0:
        return 'BREAKING_DOWN'
    if percentile <= 30:
        return 'SOFT'
    return 'NEUTRAL'

def thesis_for(scope, regime, etf_long, etf_short):
    if regime == 'BREAKING_OUT':
        if scope == 'em':
            return 'EM-USD breaking out - long ' + etf_long + ', short EEM/EMB; classic EM stress regime'
        return 'USD breaking out - long ' + etf_long + ', headwind for commodities (GLD/USO short or hedge), pressure on EM'
    if regime == 'STRONG':
        if scope == 'em':
            return 'EM-USD elevated - EM equities / EM debt face FX drag; hedge or trim EEM/EMB longs'
        return 'USD strong - modest tailwind for ' + etf_long + ', growth multiples compress'
    if regime == 'BREAKING_DOWN':
        if scope == 'em':
            return 'EM-USD breaking down - long EEM, EMB, EM-currency carry trades back on'
        return 'USD breaking down - long ' + etf_short + ', long commodities (DBC/GLD), risk-on EM'
    if regime == 'SOFT':
        if scope == 'em':
            return 'EM-USD soft - gradual EM bid; rotate into EEM, EM small-caps'
        return 'USD soft - favorable for international equities (EFA, EEM), commodities firm'
    return 'No regime shift - track for momentum break above 90th or below 10th percentile'

rows = []
for si in range(len(SERIES)):
    ent = SERIES[si]
    ser_id = ent['id']
    desc = ent['desc']
    scope = ent['scope']
    etf_long = ent['long']
    etf_short = ent['short']
    try:
        resp = requests.get(
            BASE,
            params={
                'series_id': ser_id,
                'api_key': API_KEY,
                'file_type': 'json',
                'sort_order': 'desc',
                'limit': 380,
            },
            timeout=30,
        )
        resp.raise_for_status()
        payload = resp.json() or {}
        obs = payload.get('observations', []) or []
    except Exception:
        continue
    values = []
    for oi in range(len(obs)):
        o = obs[oi]
        if not isinstance(o, dict):
            continue
        v = o.get('value', '.')
        if v == '.' or v is None:
            continue
        try:
            fv = float(v)
        except Exception:
            continue
        values.append({'date': str(o.get('date', '') or ''), 'value': fv})
    if not values:
        continue
    latest = values[0]['value']
    latest_date = values[0]['date']
    idx_30 = 29 if 29 < len(values) else len(values) - 1
    idx_90 = 89 if 89 < len(values) else len(values) - 1
    idx_1y = 251 if 251 < len(values) else len(values) - 1
    v30 = values[idx_30]['value']
    v90 = values[idx_90]['value']
    v1y = values[idx_1y]['value']
    ch30 = compute_change_pct(latest, v30)
    ch90 = compute_change_pct(latest, v90)
    ch1y = compute_change_pct(latest, v1y)
    history_1y = []
    for vi in range(len(values)):
        if vi >= 252:
            break
        history_1y.append(values[vi]['value'])
    pct = compute_percentile(history_1y, latest)
    regime = classify_regime(pct, ch30)
    thesis = thesis_for(scope, regime, etf_long, etf_short)
    rows.append({
        'series_id': ser_id,
        'description': desc,
        'index_scope': scope,
        'latest_value': round(latest, 4),
        'latest_date': latest_date,
        'value_30d_ago': round(v30, 4),
        'value_90d_ago': round(v90, 4),
        'value_1y_ago': round(v1y, 4),
        'change_30d_pct': ch30,
        'change_90d_pct': ch90,
        'change_1y_pct': ch1y,
        'percentile_1y': pct,
        'regime_flag': regime,
        'investment_thesis': thesis,
        'etf_long': etf_long,
        'etf_short': etf_short,
        '_epoch': now_epoch,
    })

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
